FULL_INERTIA = {"12x4": (4, 4, 0), "8x6": (6, 6, 0)}
WRAP_HOMOGENEOUS = {"12x4": (16, 32), "8x6": (0, 72)}
WRAP_INHOMOGENEOUS = {"12x4": (16, 32), "8x6": (36, 72)}
RANK_SYMBOLIC = (16, 16, 16, 16, 8)    # real, ker, hop, hop-dim, complex
RANK_NUMERIC = (8, 24, 8, 16, 4)
ADMISSIBLE_LOCKS = {
    "1": ((4, 0, 0), (8, 0, 0)),
    "diag(1,1,1,4)": ((4, 0, 0), (8, 0, 0)),
    "diag(1,1,1,0)": ((3, 0, 1), (7, 1, 0)),
    "diag(1,1,1,-1)": ((3, 1, 0), (7, 1, 0)),
    "diag(1,1,0,0)": ((2, 0, 2), (6, 2, 0)),
    "1 + herm(S)": ((3, 0, 1), (7, 1, 0)),
}
WITNESS_RATIOS = (R(2689, 4104), R(2431, 3591), R(667, 912))


class Bench:
    """One (size, fixed slice) bench: the committed region objects, IMPORTED."""

    def __init__(self, fx, c: int) -> None:
        self.fx = fx
        self.c = c
        self.lx = fx.LX
        self.label = next(l for l in fx.x_trivial if fx.fixed_slice(l) == c)
        self.desc = fx.descent(self.label)
        self.rows = fx.slice_rows(c, c + 1)
        self.pin = b166.region_pin(fx, [c - 1, c])
        self.hodge = b166.ssubs(fx.H_free, self.pin)
        self.action = fx.quotient_action(fx.edge_d[(0, 0)], self.hodge, MASS)
        self.pair0 = fx.pairing(self.desc, self.action, self.rows)

    def with_dq(self, delta_q: dict) -> sp.Matrix:
        return self.fx.pairing(self.desc, sadd(self.action, delta_q), self.rows)

    def carrier(self, sigma=BENCH_SIGMA, mass=None) -> dict:
        sub = b166.carrier_substitution(
            self.fx, b166.graded_carrier(self.fx, self.c, sigma))
        sub[SX] = BENCH_SX
        if mass is not None:
            sub[MASS] = mass
        return sub


def cover_disp2(fx, V: sp.Matrix, coeff) -> dict:
    """THE IMPOSED FAMILY, built on the COVER and pushed through the COMMITTED
    antiperiodic quotient, so the wrap sign is DERIVED and not inserted."""
    out: dict = {}
    ct, lx = fx.COVER_T, fx.LX
    for t in range(ct):
        nxt = (t + 2) % ct
        for y in range(lx):
            for x in range(lx):
                if V[y, x] != 0:
                    k1 = (lx * nxt + y, lx * t + x)
                    out[k1] = out.get(k1, 0) + coeff * V[y, x]
                    k2 = (lx * t + x, lx * nxt + y)
                    out[k2] = out.get(k2, 0) + coeff * sp.conjugate(V[y, x])
    return fx.quotient(sclean(out))


def hand_disp2(fx, V: sp.Matrix, coeff) -> dict:
    """The same term written directly on the PHYSICAL lattice with the
    antiperiodic sign put in BY HAND -- the two-sided pin's control."""
    out: dict = {}
    n, lx = fx.PHYS_T, fx.LX
    for t in range(n):
        nxt = t + 2
        sign = -1 if nxt >= n else 1
        nxt %= n
        for y in range(lx):
            for x in range(lx):
                if V[y, x] != 0:
                    k1 = (lx * nxt + y, lx * t + x)
                    out[k1] = out.get(k1, 0) + coeff * sign * V[y, x]
                    k2 = (lx * t + x, lx * nxt + y)
                    out[k2] = out.get(k2, 0) + coeff * sign * sp.conjugate(V[y, x])
    return sclean(out)


def inhomogeneous_disp2(fx, c: int, W: sp.Matrix) -> dict:
    """A displacement-2 block on the single (c-1, c+1) slice pair."""
    lx = fx.LX
    out: dict = {}
    for y in range(lx):
        for x in range(lx):
            out[(lx * ((c + 1) % fx.PHYS_T) + y,
                 lx * ((c - 1) % fx.PHYS_T) + x)] = W[y, x]
            out[(lx * ((c - 1) % fx.PHYS_T) + x,
                 lx * ((c + 1) % fx.PHYS_T) + y)] = sp.conjugate(W[y, x])
    return sclean(out)


def generic_V(lx: int, tag: str = "v") -> sp.Matrix:
    return sp.Matrix(lx, lx, lambda i, j: (
        sp.Symbol(f"{tag}r_{i}_{j}", real=True)
        + I * sp.Symbol(f"{tag}i_{i}_{j}", real=True)))


GEN_SYMS = tuple(
    sp.Symbol(f"g{part}{p}{q}", real=True)
    for part in ("r", "i") for p in range(4) for q in range(4)
)
GEN_BLOCK = sp.Matrix(4, 4, lambda p, q: (
    sp.Symbol(f"gr{p}{q}", real=True) + I * sp.Symbol(f"gi{p}{q}", real=True)))
HOP_INDEX = tuple(
    k for k, s in enumerate(GEN_SYMS)
    if (int(s.name[2]) < 2) != (int(s.name[3]) < 2)
)


def connection_gen(fxx, gx, gt, gen_t) -> dict:
    """The committed healed edge-differential construction, generator pluggable.

    Byte-for-byte the committed connection constructor with E_t replaced by an
    argument.  Gate B pins it: at gen_t = E_t it reproduces the LANDED edge
    differentials entry for entry.
    """
    local = gx * EX + gt * gen_t
    rt, rx = b105.shift_lifts()
    local_d: dict = {}
    for origin in ORIGINS:
        gauge = (rt ** origin[0]) * (rx ** origin[1])
        block = sp.expand(gauge.H * local * gauge)
        out: dict = {}
        for anchor in fxx.chart_cells(origin):
            sites = fxx.cell_sites(*anchor)
            for p in range(4):
                for q in range(4):
                    if block[p, q] != 0:
                        key = (sites[p], sites[q])
                        out[key] = out.get(key, 0) + block[p, q]
        local_d[origin] = sclean(out)
    star = sadd(local_d[(0, 0)], sscale(local_d[(1, 0)], -1))
    return {
        (CHART_INDEX[a], CHART_INDEX[b]): sadd(
            local_d[a],
            sscale(star, HEALING_WEIGHTS[CHART_INDEX[b]]
                   - HEALING_WEIGHTS[CHART_INDEX[a]]),
        )
        for a in ORIGINS for b in ORIGINS
    }


def real_linear_rank(matrix: sp.MatrixBase, syms) -> int:
    """Rank of the real-linear map (syms) -> matrix, over the reals."""
    rows = []
    for i in range(matrix.rows):
        for j in range(matrix.cols):
            re, im = sp.expand(matrix[i, j]).as_real_imag()
            rows.append([sp.diff(re, s) for s in syms])
            rows.append([sp.diff(im, s) for s in syms])
    return sp.Matrix(rows).rank() if rows else 0


def signed_displacements(fx, matrix: dict) -> tuple:
    half = fx.PHYS_T // 2
    out = set()
    for (i, j) in matrix:
        raw = (j // fx.LX) - (i // fx.LX)
        out.add(((raw + half) % fx.PHYS_T) - half)
    return tuple(sorted(out))


def corner_of(fx, term: dict, c: int) -> sp.Matrix:
    """herm(Q[c-1, c+1]) -- the REFLECTED CORNER, read straight off the term."""
    md = dense(term, fx.PHYS, fx.PHYS)
    blk = sp.expand(md[fx.slice_rows(c - 1), fx.slice_rows(c + 1)])
    return sp.expand((blk + blk.H) / 2)


# ---------------------------------------------------------------------------
# B. the convention collision and the rebuild anchors
# ---------------------------------------------------------------------------
def convention_probe() -> tuple:
    """The two LANDED helpers, called on the same three matrices."""
    probes = (
        sp.diag(1, 1, 1, 1, 0, 0, 0, 0),
        sp.diag(1, 1, 1, 1, -1, -1, -1, -1),
        sp.zeros(8, 8),
    )
    pairs = []
    for matrix in probes:
        try:
            old = tuple(b163.congruence_inertia(matrix))
        except Exception:                        # the landed helper's raise path
            old = ()
        pairs.append((old, tuple(inertia(matrix))))
    landed_psd = pairs[0][0][2] == 0 and pairs[0][0][0] > 0
    here_psd = pairs[0][1][1] == 0 and pairs[0][1][0] > 0
    orders_differ = any(a != b for a, b in pairs)
    return tuple(pairs), landed_psd, here_psd, orders_differ


def anchor_probe(fixtures: dict, benches: dict) -> dict:
    out: dict = {}
    for tag in TAGS:
        fx, bench = fixtures[tag], benches[tag]
        lx = fx.LX
        landed, _ = b166.region_pairing(
            fx, SLICE_C, fx.edge_d[(0, 0)], [SLICE_C - 1, SLICE_C])
        V = generic_V(lx)
        cover = dense(cover_disp2(fx, V, G2), fx.PHYS, fx.PHYS)
        hand = dense(hand_disp2(fx, V, G2), fx.PHYS, fx.PHYS)
        dq = cover_disp2(fx, V, G2)
        out[tag] = {
            "bench_is_landed":
                sp.expand(bench.pair0 - landed) == sp.zeros(2 * lx, 2 * lx),
            "connection_anchor": all(
                sclean(connection_gen(fx, I * SX, I * ST, ET)[key])
                == sclean(fx.edge_d[key]) for key in fx.EDGE_KEYS),
            "two_sided_pin":
                sp.expand(cover - hand) == sp.zeros(fx.PHYS, fx.PHYS),
            "dq_hermitian":
                sp.expand(cover - cover.H) == sp.zeros(fx.PHYS, fx.PHYS),
            "dq_displacements": signed_displacements(fx, dq),
            "corner_hollow":
                sp.expand(bench.pair0[lx:, lx:]) == sp.zeros(lx, lx),
            "b_free_of_st":
                ST not in free_symbols_of(sp.expand(bench.pair0[:lx, :lx])),
            "c_is_linear_in_st": sp.expand(
                bench.pair0[:lx, lx:]
                - ST * sp.diff(bench.pair0[:lx, lx:], ST)) == sp.zeros(lx, lx),
            "involutive": len(fx.involutive),
            "x_trivial": len(fx.x_trivial),
        }
    return out


# ---------------------------------------------------------------------------
# C. THE CANCELLATION GATE
# ---------------------------------------------------------------------------
def cancellation_probe(fixtures: dict, benches: dict) -> dict:
    out: dict = {}

    # --- the block dictionary, measured on a slice-tagged generic Q ---------
    fx, bench = fixtures["12x4"], benches["12x4"]
    lx = fx.LX
    tagged: dict = {}
    for a in range(fx.PHYS_T):
        for b in range(fx.PHYS_T):
            for y in range(lx):
                tagged[(lx * a + y, lx * b + y)] = sp.Symbol(f"q_{a}_{b}")
    tp = fx.pairing(bench.desc, sclean(tagged), bench.rows)
    q12, q01, q02 = (sp.Symbol("q_1_2"), sp.Symbol("q_0_1"),
                     sp.Symbol("q_0_2"))
    out["dictionary_c"] = sp.expand(
        tp[0, lx] - (q12 + sp.conjugate(q01)) / 2) == 0
    out["dictionary_corner"] = sp.expand(
        tp[lx, lx] - (q02 + sp.conjugate(q02)) / 2) == 0
    qd = dense(bench.action, fx.PHYS, fx.PHYS)
    out["q_not_hermitian"] = sp.expand(qd - qd.H) != sp.zeros(fx.PHYS, fx.PHYS)

    # --- MECHANISM 1: mass parity (ansatz-free, symbolic) -------------------
    mass_rows = {}
    for tag in TAGS:
        fxx, bn = fixtures[tag], benches[tag]
        lxx = fxx.LX
        act_off = fxx.quotient_action(fxx.edge_d[(0, 0)], fxx.H_free, MASS)
        p_off = fxx.pairing(bn.desc, act_off, bn.rows)
        c_mass = sp.expand(sp.expand(p_off[:lxx, lxx:]).subs({SX: 0, ST: 0}))
        incident = ({fxx.B[((bn.c - 1) % fxx.PHYS_T, x)] for x in range(lxx)}
                    | {fxx.B[(bn.c % fxx.PHYS_T, x)] for x in range(lxx)})
        pin_shear = {b: sp.Integer(0) for b in incident}
        mass_rows[tag] = {
            "row0": tuple(sp.simplify(c_mass[0, j]) for j in range(lxx)),
            "symbols_incident_only":
                free_symbols_of(c_mass) <= incident | {MASS},
            "nonzero": c_mass != sp.zeros(lxx, lxx),
            "dies_on_the_pin":
                sp.expand(c_mass.subs(pin_shear)) == sp.zeros(lxx, lxx),
            "p_off": p_off,
        }
    out["mass_parity"] = {t: {k: v for k, v in mass_rows[t].items()
                              if k != "p_off"} for t in TAGS}

    # --- MECHANISM 2: one-sidedness over the WHOLE generator space ----------
    one_sided = {}
    for tag in TAGS:
        fxx, bn = fixtures[tag], benches[tag]
        lxx = fxx.LX
        ed = connection_gen(fxx, I * SX, I * ST, GEN_BLOCK)[(0, 0)]
        act = fxx.quotient_action(ed, bn.hodge, MASS)
        dn = dense(act, fxx.PHYS, fxx.PHYS)
        U = sp.expand(dn[fxx.slice_rows(bn.c), fxx.slice_rows(bn.c + 1)])
        W = sp.expand(dn[fxx.slice_rows(bn.c - 1), fxx.slice_rows(bn.c)])
        out_dirs = sum(1 for s in GEN_SYMS
                       if sp.expand(sp.diff(U, s)) == sp.zeros(lxx, lxx))
        in_dirs = sum(1 for s in GEN_SYMS
                      if sp.expand(sp.diff(W, s)) != sp.zeros(lxx, lxx))
        one_sided[tag] = {
            "outgoing_identically_zero": U == sp.zeros(lxx, lxx),
            "outgoing_dead_directions": out_dirs,
            "incoming_live_directions": in_dirs,
            "directions": len(GEN_SYMS),
        }
        if tag == "12x4":
            pr = fxx.pairing(bn.desc, act, bn.rows)
            out["c1_generic"] = sp.expand(sp.diff(pr[:lxx, lxx:], ST))
    out["one_sidedness"] = one_sided

    # --- the OFF-region cancellation solve (disclosed ansatz) --------------
    fx, bench = fixtures["12x4"], benches["12x4"]
    lx = fx.LX
    p_off = mass_rows["12x4"]["p_off"]
    sg = {t: sp.Symbol(f"sg{t}", real=True) for t in range(fx.PHYS_T)}
    field = {(t, x): (sg[t], sp.Integer(1)) for (t, x) in fx.CELLS}
    sub_off = b166.carrier_substitution(fx, field)
    c_off = sp.expand(sp.expand(p_off[:lx, lx:]).subs(sub_off))
    eqs = set()
    for i in range(lx):
        for j in range(lx):
            entry = sp.expand(c_off[i, j])
            if entry != 0:
                for part in entry.as_real_imag():
                    if part != 0:
                        eqs.add(sp.simplify(part))
    eqs = sorted(eqs, key=sp.default_sort_key)
    mass_eqs = [e for e in eqs if MASS in e.free_symbols]
    solutions = sp.solve(eqs, [sg[0], sg[1], SX, ST, MASS], dict=True)
    massless = [s for s in solutions
                if MASS in s and sp.simplify(s[MASS]) == 0]
    massive = [s for s in solutions if s not in massless]
    out["off_region_solve"] = {
        "equations": len(eqs),
        "mass_shear_equations": len(mass_eqs),
        "mass_equations_die_at_zero_mass": all(
            sp.simplify(e.subs({MASS: 0})) == 0 for e in mass_eqs),
        "branches": len(solutions),
        "massless_branches": len(massless),
        "massive_branches_are_flat": all(
            sp.simplify(s.get(sg[0], sp.Integer(0))) == 0
            and sp.simplify(s.get(sg[1], sp.Integer(0))) == 0
            for s in massive),
    }

    # --- the massless points: never PSD WITH POSITIVE CONTENT --------------
    u_off = dense(fx.quotient_action(fx.edge_d[(0, 0)], fx.H_free, MASS),
                  fx.PHYS, fx.PHYS)
    U_off = sp.expand(u_off[fx.slice_rows(bench.c), fx.slice_rows(bench.c + 1)])
    W_off = sp.expand(u_off[fx.slice_rows(bench.c - 1), fx.slice_rows(bench.c)])
    rows = []
    for s in massless:
        pick = {v: (R(2, 5) if v is not MASS else sp.Integer(0))
                for v in (sg[0], sg[1], SX, ST, MASS) if v not in s}
        try:
            Cn = sp.expand(c_off.subs(s).subs(pick))
            Pn = sp.expand(sp.expand(p_off.subs(sub_off)).subs(s).subs(pick))
            if Cn != sp.zeros(lx, lx) or not no_float(Pn):
                continue
            Un = sp.expand(sp.expand(U_off.subs(sub_off)).subs(s).subs(pick))
            Wn = sp.expand(sp.expand(W_off.subs(sub_off)).subs(s).subs(pick))
            rows.append((Un.rank(), Wn.rank(), tuple(inertia(Pn))))
        except (TypeError, ValueError):
            continue
    out["massless_points"] = tuple(rows)
    out["massless_never_positive"] = bool(rows) and all(
        triple[0] == 0 or triple[1] > 0 for (_, _, triple) in rows)

    # --- the carrier-locked E02 witness, disposed of -----------------------
    ratio = sp.Symbol("ratio", real=True)
    wr = sp.zeros(4, 4)
    wr[0, 2] = sp.Integer(1)
    wr[2, 0] = ratio
    pr_r = fx.pairing(
        bench.desc,
        fx.quotient_action(connection_gen(fx, I * SX, I * ST, wr)[(0, 0)],
                           bench.hodge, MASS),
        bench.rows)
    c1_r = sp.expand(sp.diff(pr_r[:lx, lx:], ST))
    ratios = []
    for sigma in KAPPA_SIGMAS[:3]:
        sub = bench.carrier(sigma, BENCH_MASS)
        found = set()
        Cn = sp.expand(c1_r.subs(sub))
        for i in range(lx):
            for j in range(lx):
                entry = sp.expand(Cn[i, j])
                if entry != 0:
                    for part in entry.as_real_imag():
                        if part != 0:
                            found.add(sp.simplify(part))
        sol = sp.solve(list(found), [ratio], dict=True)
        ratios.append(sol[0][ratio] if sol else None)
    wit = sp.zeros(4, 4)
    wit[0, 2] = sp.Integer(1)
    wit[2, 0] = R(667, 912)
    act_w = fx.quotient_action(
        connection_gen(fx, I * SX, I * ST, wit)[(0, 0)], bench.hodge, MASS)
    C_w = sp.expand(fx.pairing(bench.desc, act_w, bench.rows)[:lx, lx:])
    dnw = dense(act_w, fx.PHYS, fx.PHYS)
    subw = bench.carrier(BENCH_SIGMA, BENCH_MASS)
    Uw = sp.expand(dnw[fx.slice_rows(bench.c), fx.slice_rows(bench.c + 1)]
                   ).subs(subw).subs({ST: R(1, 2)})
    Ww = sp.expand(dnw[fx.slice_rows(bench.c - 1), fx.slice_rows(bench.c)]
                   ).subs(subw).subs({ST: R(1, 2)})
    out["witness"] = {
        "ratios": tuple(ratios),
        "c_nonzero_symbolically": C_w != sp.zeros(lx, lx),
        "distinct_ratios": len(set(ratios)),
        "outgoing_rank_at_own_carrier": sp.expand(Uw).rank(),
        "incoming_rank_at_own_carrier": sp.expand(Ww).rank(),
    }
    return out


# ---------------------------------------------------------------------------
# D. THE SHIM THEOREM
# ---------------------------------------------------------------------------
def shim_probe(fixtures: dict, benches: dict) -> dict:
    out: dict = {}
    fx, bench = fixtures["12x4"], benches["12x4"]
    lx = fx.LX
    sub = bench.carrier(BENCH_SIGMA, BENCH_MASS)

    # --- the closed form, as a matrix identity against the framework -------
    dq2 = cover_disp2(fx, sp.eye(lx), G2 * ST ** 2)
    P2 = sp.expand(bench.with_dq(dq2).subs(sub))
    B = sp.expand(bench.pair0[:lx, :lx].subs({ST: 0}).subs(sub))
    C1 = sp.expand(sp.diff(bench.pair0[:lx, lx:], ST).subs(sub))
    closed = sp.Matrix(sp.BlockMatrix(
        [[B, ST * C1], [ST * C1.H, G2 * ST ** 2 * sp.eye(lx)]]))
    out["closed_form"] = sp.expand(P2 - closed) == sp.zeros(2 * lx, 2 * lx)

    # --- THE SHIM EQUIVALENCE: no action term at all -----------------------
    bare = sp.expand(bench.pair0
                     + sp.diag(sp.zeros(lx, lx), G2 * ST ** 2 * sp.eye(lx)))
    out["bare_shim_reproduces"] = sp.expand(
        bench.with_dq(dq2) - bare) == sp.zeros(2 * lx, 2 * lx)

    # --- the Schur criterion, with s_t CANCELLING IDENTICALLY --------------
    criterion = sp.expand(G2 * B - C1 * C1.H)
    out["criterion_is_st_free"] = ST not in free_symbols_of(criterion)
    kappa = {}
    scalar_ok = True
    for tag in TAGS:
        fxx, bn = fixtures[tag], benches[tag]
        lxx = fxx.LX
        values = set()
        for sigma in KAPPA_SIGMAS:
            sb = bn.carrier(sigma)
            Bx = sp.expand(bn.pair0[:lxx, :lxx].subs({ST: 0}).subs(sb))
            C1x = sp.expand(sp.diff(bn.pair0[:lxx, lxx:], ST).subs(sb))
            sch = sp.expand(C1x.H * Bx.inv() * C1x)
            if sp.expand(sch - sch[0, 0] * sp.eye(lxx)) != sp.zeros(lxx, lxx):
                scalar_ok = False
            values.add(sp.expand(sch[0, 0] * MASS))
        kappa[tag] = tuple(sorted(values, key=sp.default_sort_key))
    out["kappa"] = kappa
    out["kappa_is_scalar"] = scalar_ok

    # --- the boundary at eps = 1e-9, at TEN s_t including +-1000 ----------
    boundary = []
    for s in ST_GRID:
        below = tuple(inertia(sp.expand(
            P2.subs({G2: MARGIN_CONSTANT - BOUNDARY_EPS, ST: s}))))
        at = tuple(inertia(sp.expand(P2.subs({G2: MARGIN_CONSTANT, ST: s}))))
        above = tuple(inertia(sp.expand(
            P2.subs({G2: MARGIN_CONSTANT + BOUNDARY_EPS, ST: s}))))
        rank_c = sp.expand(P2.subs({G2: MARGIN_CONSTANT, ST: s})
                           )[:lx, lx:].rank()
        boundary.append((s, below, at, above, rank_c))
    out["boundary"] = tuple(boundary)
    out["boundary_ok"] = sum(
        1 for (_, b, a, ab, rk) in boundary
        if b == (lx, lx, 0) and a == (lx, 0, lx) and ab == (2 * lx, 0, 0)
        and rk == lx)

    # --- rank C was ALREADY L_x at g_2 = 0 --------------------------------
    out["rank_c_at_zero_coupling"] = tuple(
        sp.expand(P2.subs({G2: 0, ST: s}))[:lx, lx:].rank() for s in ST_GRID)

    # --- THE MASS LAW at 30 (sigma, mass) pairs ---------------------------
    mass_law = 0
    mass_cells = 0
    for sigma in KAPPA_SIGMAS:
        for mass in KAPPA_MASSES:
            sb = bench.carrier(sigma, mass)
            Pm = sp.expand(bench.with_dq(dq2).subs(sb))
            star = sp.expand(MARGIN_CONSTANT / mass)
            probe = R(1, 2)
            below = tuple(inertia(sp.expand(
                Pm.subs({G2: star - BOUNDARY_EPS, ST: probe}))))
            at = tuple(inertia(sp.expand(Pm.subs({G2: star, ST: probe}))))
            above = tuple(inertia(sp.expand(
                Pm.subs({G2: star + BOUNDARY_EPS, ST: probe}))))
            mass_cells += 1
            mass_law += int(below == (lx, lx, 0) and at == (lx, 0, lx)
                            and above == (2 * lx, 0, 0))
    out["mass_law"] = (mass_law, mass_cells)

    # --- the calibration, exactly ------------------------------------------
    calibration = {}
    for tag in TAGS:
        fxx, bn = fixtures[tag], benches[tag]
        lxx = fxx.LX
        trace_d = b166.hodge_trace_D(fxx)
        want = sp.zeros(2 * lxx, 2 * lxx)
        for x in range(lxx):
            want[x, x] = MASS * sp.expand(trace_d[(bn.c, x)].subs(bn.pin))
        flat = {}
        for key in fxx.CELLS:
            flat[fxx.NU[key]] = sp.Integer(1)
            flat[fxx.A[key]] = sp.Integer(1)
            flat[fxx.B[key]] = sp.Integer(0)
            flat[fxx.MU[key]] = sp.Integer(1)
        dq = cover_disp2(fxx, sp.eye(lxx), G2 * ST ** 2)
        calibration[tag] = {
            "committed": sp.expand(bn.pair0.subs({ST: 0}) - want)
                         == sp.zeros(2 * lxx, 2 * lxx),
            "flat": sp.expand(bn.pair0.subs({ST: 0}).subs(flat)
                              - MASS * sp.diag(*([1] * lxx + [0] * lxx)))
                    == sp.zeros(2 * lxx, 2 * lxx),
            "preserved_by_k2": sp.expand(
                bn.with_dq(dq).subs({ST: 0}) - bn.pair0.subs({ST: 0}))
                == sp.zeros(2 * lxx, 2 * lxx),
        }
    out["calibration"] = calibration

    # --- P > 0 IS NECESSARY -----------------------------------------------
    shift = sp.Matrix(lx, lx, lambda i, j: 1 if (j - i) % lx == 1 else 0)
    corners = {
        "1": sp.eye(lx),
        "diag(1,1,1,4)": sp.diag(1, 1, 1, 4),
        "diag(1,1,1,0)": sp.diag(1, 1, 1, 0),
        "diag(1,1,1,-1)": sp.diag(1, 1, 1, -1),
        "diag(1,1,0,0)": sp.diag(1, 1, 0, 0),
        "1 + herm(S)": sp.expand(sp.eye(lx) + (shift + shift.T) / 2),
    }
    census = {}
    for name, P in corners.items():
        Pp = sp.expand(bench.with_dq(cover_disp2(fx, P, G2 * ST ** 2)).subs(sub))
        row = tuple(tuple(inertia(sp.expand(Pp.subs({G2: g, ST: R(1, 2)}))))
                    for g in (sp.Integer(1), sp.Integer(10),
                              sp.Integer(10) ** 6))
        census[name] = (tuple(inertia(P)), row)
    out["admissible"] = census

    # --- THE BLINDNESS BATTERY -------------------------------------------
    V = generic_V(lx)
    corner_g = sp.expand((bench.with_dq(cover_disp2(fx, V, G2))
                          - bench.pair0)[lx:, lx:])
    geometry = {SX, ST, MASS} | set(fx.SHEARS) \
        | set(fx.NU.values()) | set(fx.A.values()) | set(fx.MU.values())
    out["corner_symbols_geometry_free"] = not (
        free_symbols_of(corner_g) & geometry)
    out["corner_is_herm_v"] = sp.expand(
        corner_g - G2 * (V + V.H) / 2) == sp.zeros(lx, lx)
    ed_h = connection_gen(fx, I * SX, GRE + I * GIM, ET)[(0, 0)]
    act_h = fx.quotient_action(ed_h, bench.hodge, MASS)
    pr_h = fx.pairing(bench.desc, act_h, bench.rows)
    pr_h2 = fx.pairing(bench.desc, sadd(act_h, cover_disp2(fx, V, G2)),
                       bench.rows)
    out["holonomy_moves_c"] = bool(
        {GRE, GIM} & free_symbols_of(sp.expand(pr_h[:lx, lx:])))
    out["holonomy_blind_corner"] = sp.expand(
        (pr_h2 - pr_h)[lx:, lx:] - corner_g) == sp.zeros(lx, lx)

    # --- the corner slot IS a genuine two-step slot, but only the slot -----
    live_pairs = 0
    for t0 in range(fx.PHYS_T):
        W = generic_V(lx, f"w{t0}")
        dq_i = {}
        for y in range(lx):
            for x in range(lx):
                dq_i[(lx * ((t0 + 2) % fx.PHYS_T) + y, lx * t0 + x)] = W[y, x]
                dq_i[(lx * t0 + x, lx * ((t0 + 2) % fx.PHYS_T) + y)] = \
                    sp.conjugate(W[y, x])
        delta = sp.expand((bench.with_dq(sclean(dq_i)) - bench.pair0)[lx:, lx:])
        live_pairs += int(delta != sp.zeros(lx, lx))
    out["corner_live_slice_pairs"] = (live_pairs, fx.PHYS_T)

    # --- "k = 2 IS THE UNIQUE POWER" -- REFUTED ---------------------------
    k_rows = {}
    for k in K_POWERS:
        dqk = cover_disp2(fx, sp.eye(lx), G2 * ST ** k)
        Pk = sp.expand(bench.with_dq(dqk).subs(sub))
        kept = sp.expand(Pk.subs({ST: 0}) - sp.expand(
            bench.pair0.subs(sub).subs({ST: 0}))) == sp.zeros(2 * lx, 2 * lx)
        thresholds = tuple(sp.expand(MARGIN_CONSTANT * s ** 2 / s ** k)
                           for s in K_SIGN_PROBES)
        sign_safe = all(t > 0 for t in thresholds)
        reaches = sign_safe and all(
            tuple(inertia(sp.expand(Pk.subs(
                {G2: th + BOUNDARY_EPS, ST: s})))) == (2 * lx, 0, 0)
            and sp.expand(Pk.subs({G2: th + BOUNDARY_EPS, ST: s})
                          )[:lx, lx:].rank() == lx
            for s, th in zip(K_SIGN_PROBES, thresholds))
        k_rows[k] = (kept, sign_safe, reaches)
    out["k_table"] = k_rows
    out["k_working"] = tuple(
        k for k in K_POWERS if k >= 1 and all(k_rows[k]))
    functions = (ST ** 2, ST ** 4, ST ** 2 * (1 + ST ** 2), ST ** 6,
                 7 * ST ** 2)
    f_ok = 0
    for f in functions:
        dqf = cover_disp2(fx, sp.eye(lx), G2 * f)
        Pf = sp.expand(bench.with_dq(dqf).subs(sub))
        good = True
        for s in (R(1, 2), -R(1, 2)):
            th = sp.expand(MARGIN_CONSTANT * s ** 2 / f.subs({ST: s}))
            lo = tuple(inertia(sp.expand(
                Pf.subs({G2: th - BOUNDARY_EPS, ST: s}))))
            hi = tuple(inertia(sp.expand(
                Pf.subs({G2: th + BOUNDARY_EPS, ST: s}))))
            good = good and lo == (lx, lx, 0) and hi == (2 * lx, 0, 0)
        f_ok += int(good)
    out["function_freedom"] = (f_ok, len(functions))
    return out


# ---------------------------------------------------------------------------
# E. THE ZERO-DIAGONAL LEMMA
# ---------------------------------------------------------------------------
def zero_diagonal_probe(fixtures: dict, benches: dict) -> dict:
    out: dict = {}
    objects = {}
    for tag in TAGS:
        fxx, bn = fixtures[tag], benches[tag]
        lxx = fxx.LX
        d = fxx.edge_d[(0, 0)]
        candidates = {
            "committed action, on the region": bn.action,
            "committed action, off the region":
                fxx.quotient_action(d, fxx.H_free, MASS),
            "quotient(d^H H d)":
                fxx.quotient(smul(sdagger(d), smul(fxx.H_free, d))),
            "quotient(H d + d^H H)":
                fxx.quotient(sadd(smul(fxx.H_free, d),
                                  smul(sdagger(d), fxx.H_free))),
        }
        rows = {}
        for name, term in candidates.items():
            corner = corner_of(fxx, term, bn.c)
            rows[name] = {
                "nonzero": corner != sp.zeros(lxx, lxx),
                "diagonal_identically_zero": all(
                    sp.expand(corner[k, k]) == 0 for k in range(lxx)),
                "traceless": sp.expand(sp.trace(corner)) == 0,
            }
        objects[tag] = rows
        if tag == "12x4":
            out["d_squared_zero"] = smul(d, d) == {}
    out["objects"] = objects

    # --- the contrast: the IMPOSED corner has trace 4 g_2 ------------------
    fx, bench = fixtures["12x4"], benches["12x4"]
    lx = fx.LX
    imposed = sp.expand((bench.with_dq(cover_disp2(fx, sp.eye(lx), G2))
                         - bench.pair0)[lx:, lx:])
    out["imposed_trace"] = sp.expand(sp.trace(imposed))

    # --- THE CENSUS: off-region, 0 admissible corners of 300 --------------
    d = fx.edge_d[(0, 0)]
    total = sadd(fx.quotient_action(d, fx.H_free, MASS),
                 sscale(fx.quotient(smul(sdagger(d), smul(fx.H_free, d))),
                        LAMW))
    corner_off = corner_of(fx, total, bench.c)
    base = bench.carrier(BENCH_SIGMA, BENCH_MASS)
    free_shears = sorted(
        (s for s in free_symbols_of(corner_off) if s in fx.SHEARS),
        key=lambda s: s.name)
    for s in free_shears:
        base.pop(s, None)
    core = sp.expand(corner_off.subs(base))
    signatures: dict = {}
    admissible = 0
    cells = 0
    full_rank = 0
    full_rank_signatures: dict = {}
    lxx = fx.LX
    for shears in CENSUS_SHEARS:
        pin = dict(zip(free_shears, shears))
        for s_t in CENSUS_ST:
            for lam in CENSUS_LAMW:
                probe = sp.expand(core.subs(pin).subs({ST: s_t, LAMW: lam}))
                triple = tuple(inertia(probe))
                signatures[triple] = signatures.get(triple, 0) + 1
                cells += 1
                admissible += int(triple[1] == 0 and triple[0] > 0)
                if triple[2] == 0:
                    full_rank += 1
                    full_rank_signatures[triple] = \
                        full_rank_signatures.get(triple, 0) + 1
    out["census"] = {
        "free_shears": tuple(str(s) for s in free_shears),
        "cells": cells,
        "admissible": admissible,
        "signatures": tuple(sorted(signatures.items(),
                                   key=lambda kv: str(kv[0]))),
        "full_rank_cells": full_rank,
        "full_rank_signatures": tuple(sorted(full_rank_signatures.items(),
                                             key=lambda kv: str(kv[0]))),
    }
    # THE LEMMA'S CONSEQUENCE, read off the census rather than asserted: every
    # signature carries a NEGATIVE direction, at full rank and on the
    # rank-deficient stratum alike, so no cell is PSD with positive content.
    out["traceless_nonzero_never_psd"] = all(
        triple[1] > 0 for triple, _ in out["census"]["signatures"]
        if triple != (0, 0, lxx))
    return out


# ---------------------------------------------------------------------------
# F. THE DIAGNOSTIC ADJUDICATION
# ---------------------------------------------------------------------------
def diagnostic_probe(fixtures: dict, benches: dict) -> dict:
    out: dict = {}
    rows = {}
    for tag in TAGS:
        fxx, bn = fixtures[tag], benches[tag]
        lxx = fxx.LX
        sub = bn.carrier(BENCH_SIGMA, BENCH_MASS)
        dq2 = cover_disp2(fxx, sp.eye(lxx), G2 * ST ** 2)
        Pg = bn.with_dq(dq2)
        C0 = sp.expand(bn.pair0[:lxx, lxx:])
        Cg = sp.expand(Pg[:lxx, lxx:])
        C1 = sp.expand(sp.diff(C0, ST))
        one = sp.expand(Cg.subs({ST: -ST}).H * Cg)
        md = dense(sadd(bn.action, dq2), fxx.PHYS, fxx.PHYS)
        K = sp.expand(md[fxx.slice_rows(bn.c - 1), fxx.slice_rows(bn.c + 1)])
        two = sp.expand(K.subs({ST: -ST}).H * K)
        full = {}
        for g in (sp.Integer(0), sp.Integer(1)):
            Ps = sp.expand(Pg.subs(sub).subs({G2: g}))
            Mx = sp.expand(Ps.subs({ST: -ST}).H * Ps)
            full[g] = tuple(inertia(sp.expand(
                ((Mx + Mx.H) / 2).subs({ST: R(1, 2)}))))
        rows[tag] = {
            "c_untouched": sp.expand(Cg - C0) == sp.zeros(lxx, lxx),
            "one_step_identity": sp.expand(
                one + ST ** 2 * (C1.H * C1)) == sp.zeros(lxx, lxx),
            "one_step_inertia": tuple(inertia(sp.expand(
                one.subs(sub).subs({ST: R(1, 2), G2: sp.Integer(1)})))),
            "two_step_even":
                sp.expand(K.subs({ST: -ST}) - K) == sp.zeros(lxx, lxx),
            "two_step_inertia": tuple(inertia(sp.expand(
                two.subs(sub).subs({ST: R(1, 2), G2: sp.Integer(1)})))),
            "full_inertia": (full[sp.Integer(0)], full[sp.Integer(1)]),
        }
    out["rows"] = rows

    # --- the structural lemma: Delta Q touches ONLY the corner -------------
    lemma = {}
    for tag in TAGS:
        fxx = fixtures[tag]
        lxx = fxx.LX
        labels = fxx.x_trivial
        b_clean = c_clean = corner_live = 0
        for lab in labels:
            bn = Bench(fxx, fxx.fixed_slice(lab))
            V = generic_V(lxx)
            delta = sp.expand(bn.with_dq(cover_disp2(fxx, V, G2)) - bn.pair0)
            b_clean += int(sp.expand(delta[:lxx, :lxx]) == sp.zeros(lxx, lxx))
            c_clean += int(sp.expand(delta[:lxx, lxx:]) == sp.zeros(lxx, lxx))
            corner_live += int(sp.expand(delta[lxx:, lxx:])
                               != sp.zeros(lxx, lxx))
        lemma[tag] = (b_clean, c_clean, corner_live, len(labels))
    out["structural_lemma"] = lemma
    return out


# ---------------------------------------------------------------------------
# G. THE WRAP REFINEMENT AND THE RANK DISPUTE
# ---------------------------------------------------------------------------
def wrap_probe(fixtures: dict, benches: dict, c1_generic: sp.Matrix) -> dict:
    out: dict = {}
    rows = {}
    for tag in TAGS:
        fxx, bn = fixtures[tag], benches[tag]
        lxx = fxx.LX
        V = generic_V(lxx)
        vs = tuple(sorted(V.free_symbols, key=lambda s: s.name))
        dq = cover_disp2(fxx, V, sp.Integer(1))
        corner_h = sp.expand((bn.with_dq(dq) - bn.pair0)[lxx:, lxx:])
        W = generic_V(lxx, "w")
        ws = tuple(sorted(W.free_symbols, key=lambda s: s.name))
        corner_i = sp.expand(
            (bn.with_dq(inhomogeneous_disp2(fxx, bn.c, W)) - bn.pair0
             )[lxx:, lxx:])
        q = dense(dq, fxx.PHYS, fxx.PHYS)
        blk = sp.expand(q[fxx.slice_rows(bn.c - 1), fxx.slice_rows(bn.c + 1)])
        rows[tag] = {
            "homogeneous": (real_linear_rank(corner_h, vs), len(vs)),
            "inhomogeneous": (real_linear_rank(corner_i, ws), len(ws)),
            "surviving_block_anti_hermitian":
                sp.expand(blk + blk.H) == sp.zeros(lxx, lxx)
                and blk != sp.zeros(lxx, lxx),
        }
    out["rows"] = rows

    # --- THE RANK DISPUTE, settled ----------------------------------------
    bench = benches["12x4"]

    def rank_row(sub=None):
        Cx = sp.expand(c1_generic.subs(sub)) if sub else c1_generic
        lxx = Cx.rows
        real_rows = []
        for i in range(lxx):
            for j in range(lxx):
                re, im = sp.expand(Cx[i, j]).as_real_imag()
                real_rows.append([sp.diff(re, s) for s in GEN_SYMS])
                real_rows.append([sp.diff(im, s) for s in GEN_SYMS])
        real_rank = sp.Matrix(real_rows).rank()
        hop_rank = sp.Matrix(
            [[row[k] for k in HOP_INDEX] for row in real_rows]).rank()
        live = [(i, j) for i in range(lxx) for j in range(lxx)
                if sp.expand(Cx[i, j]) != 0]
        entry = sp.Matrix(
            len(live), len(GEN_SYMS),
            lambda r, k: sp.expand(
                sp.diff(Cx[live[r][0], live[r][1]], GEN_SYMS[k])))
        return (real_rank, len(GEN_SYMS) - real_rank, hop_rank,
                len(HOP_INDEX), entry.rank())

    out["rank_symbolic"] = rank_row()
    out["rank_numeric"] = tuple(
        rank_row(bench.carrier(sigma, BENCH_MASS))
        for sigma in KAPPA_SIGMAS[:3])
    return out


# ---------------------------------------------------------------------------
# measured facts (computed once, before any mutation flag is consulted)
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    convention: tuple
    anchors: dict
    cancellation: dict
    shim: dict
    zero_diagonal: dict
    diagnostics: dict
    wrap: dict
    deep: bool
    exact_no_float: bool
    scope: dict


def measure(deep: bool) -> Facts:
    main_head = git_output("rev-parse", "origin/main")
    authority = authority_certificate(main_head)

    fixtures = {tag: b166.Fixture(cover_t, lx, tag)
                for tag, cover_t, lx in FIXTURE_SPECS}
    benches = {tag: Bench(fixtures[tag], SLICE_C) for tag in TAGS}

    convention = convention_probe()
    anchors = anchor_probe(fixtures, benches)
    cancellation = cancellation_probe(fixtures, benches)
    shim = shim_probe(fixtures, benches)
    zero_diagonal = zero_diagonal_probe(fixtures, benches)
    diagnostics = diagnostic_probe(fixtures, benches)
    wrap = wrap_probe(fixtures, benches, cancellation["c1_generic"])

    scalars: list = [
        MARGIN_CONSTANT,
        shim["kappa"]["12x4"], shim["kappa"]["8x6"],
        tuple(cancellation["witness"]["ratios"]),
        cancellation["mass_parity"]["12x4"]["row0"],
        cancellation["mass_parity"]["8x6"]["row0"],
        zero_diagonal["imposed_trace"],
        KAPPA_SIGMAS, KAPPA_MASSES, ST_GRID, BOUNDARY_EPS,
        CENSUS_SHEARS, CENSUS_ST, CENSUS_LAMW,
    ]
    if deep:
        scalars.append(tuple(row[0] for row in shim["boundary"]))
    exact = all(no_float(value) for value in scalars)

    return Facts(
        main_head=main_head,
        authority=authority,
        convention=convention,
        anchors=anchors,
        cancellation={k: v for k, v in cancellation.items()
                      if k != "c1_generic"},
        shim=shim,
        zero_diagonal=zero_diagonal,
        diagnostics=diagnostics,
        wrap=wrap,
        deep=deep,
        exact_no_float=exact,
        scope=scope_certificate(raw_note()),
    )


