def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "lane_conventions_uniform": False,
        "cancellation_locus_nonempty": False,
        "schur_threshold": MARGIN_CONSTANT,
        "shim_carries_transport": False,
        "k2_unique": False,
        "zero_diagonal_holds": True,
        "in_framework_corner_admissible": False,
        "collision_open": False,
        "composite_repairable": False,
        "homogeneity_kills": True,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "claim_convention_uniform":
        # THE BANNER DENIED: the lane asserted to carry ONE inertia convention,
        # which the two-helper comparison on identical matrices forbids
        claims["lane_conventions_uniform"] = True
    elif mutation == "break_cancellation_locus":
        # THE CANCELLATION GATE DENIED: a live-block cancellation point asserted
        # to exist, which mass parity and one-sidedness together forbid
        claims["cancellation_locus_nonempty"] = True
    elif mutation == "break_schur_criterion":
        # THE THRESHOLD DENIED at its constant: the exact Schur boundary
        # asserted to be a different rational, which the 10 s_t x 30 (sigma, m)
        # below/at/above measurement forbids
        claims["schur_threshold"] = R(57, 161)
    elif mutation == "claim_shim_carries_transport":
        # THE STRUCK PHYSICS READING RE-ASSERTED: the rank-4 corner claimed to
        # carry connection content, which the blindness census, the bare
        # pairing-diagonal shim and rank C = L_x at g_2 = 0 all forbid
        claims["shim_carries_transport"] = True
    elif mutation == "claim_k2_unique":
        # THE REFUTED UNIQUENESS RE-ASSERTED: k = 2 claimed to be the unique
        # working power, which k = 4 and k = 6 forbid
        claims["k2_unique"] = True
    elif mutation == "break_zero_diagonal":
        # THE LEMMA DENIED: some in-framework corner asserted to have a nonzero
        # diagonal entry, which the symbolic measurement at both sizes forbids
        claims["zero_diagonal_holds"] = False
    elif mutation == "claim_in_framework_admissible":
        # THE LEMMA'S CONSEQUENCE DENIED: an admissible in-framework corner
        # asserted to exist, which the 0-of-300 census forbids
        claims["in_framework_corner_admissible"] = True
    elif mutation == "claim_collision_open":
        # THE HANDOFF RE-OPENED: the would-be Block 169 collision question
        # asserted still open, which the zero-diagonal lemma closes
        claims["collision_open"] = True
    elif mutation == "claim_composite_repairable":
        # THE ADJUDICATION DENIED: the doubled-step composite asserted
        # repairable by the shim family, which C-untouchedness forbids
        claims["composite_repairable"] = True
    elif mutation == "break_wrap_refinement":
        # THE WRAP REFINEMENT DENIED: displacement 2 rather than homogeneity
        # asserted to be what T_phys = 4 kills, which the 0/72 against 36/72
        # corner ranks forbid
        claims["homogeneity_kills"] = False
    elif mutation == "drop_remaining_axes":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key not in AXES_KEYS
        )
    elif mutation == "drop_cycle913":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key not in CAUTION_KEYS
        )
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim"
        )
    return claims


