    zero = facts.zero_diagonal
    diagonal_holds = all(
        row["diagonal_identically_zero"] and row["traceless"]
        for tag in TAGS for row in zero["objects"][tag].values()
    )
    census = zero["census"]
    admissible = census["admissible"] > 0
    gate_e = bool(
        diagonal_holds == claims["zero_diagonal_holds"]
        and all(
            zero["objects"][tag][name]["nonzero"]
            for tag in TAGS
            for name in ("committed action, off the region",
                         "quotient(d^H H d)", "quotient(H d + d^H H)")
        )
        and zero["objects"]["12x4"]["committed action, on the region"]["nonzero"]
        is False
        and zero["objects"]["8x6"]["committed action, on the region"]["nonzero"]
        and zero["d_squared_zero"]
        and sp.expand(zero["imposed_trace"] - 4 * G2) == 0
        and census["free_shears"] == ("b_1_0", "b_1_1", "b_1_2", "b_1_3")
        and census["cells"] == 300
        and len(CENSUS_SHEARS) * len(CENSUS_ST) * len(CENSUS_LAMW) == 300
        and census["full_rank_cells"] == 240
        and census["full_rank_signatures"] == (((2, 2, 0), 240),)
        and all(triple[1] > 0 for triple, _ in census["signatures"])
        and zero["traceless_nonzero_never_psd"]
        and admissible == claims["in_framework_corner_admissible"]
        and admissible == claims["collision_open"]
        and facts.exact_no_float
    )

    diag = facts.diagnostics
    rows = diag["rows"]
    repairable = not all(rows[tag]["c_untouched"] for tag in TAGS)
    gate_f = bool(
        all(
            rows[tag]["c_untouched"]
            and rows[tag]["one_step_identity"]
            and rows[tag]["one_step_inertia"] == ONE_STEP_INERTIA[tag]
            and rows[tag]["two_step_inertia"] == TWO_STEP_INERTIA[tag]
            and rows[tag]["full_inertia"]
            == (FULL_INERTIA[tag], FULL_INERTIA[tag])
            and rows[tag]["two_step_even"] == CORNER_HOLLOW[tag]
            for tag in TAGS
        )
        and all(
            diag["structural_lemma"][tag]
            == (PHYS_T[tag], PHYS_T[tag],
                PHYS_T[tag] if CORNER_HOLLOW[tag] else 0, PHYS_T[tag])
            for tag in TAGS
        )
        and repairable == claims["composite_repairable"]
        and facts.exact_no_float
    )

    wrap = facts.wrap
    homogeneity_kills = (
        wrap["rows"]["8x6"]["homogeneous"][0] == 0
        and wrap["rows"]["8x6"]["inhomogeneous"][0] > 0
        and wrap["rows"]["8x6"]["surviving_block_anti_hermitian"]
    )
    gate_g = bool(
        all(
            wrap["rows"][tag]["homogeneous"] == WRAP_HOMOGENEOUS[tag]
            and wrap["rows"][tag]["inhomogeneous"] == WRAP_INHOMOGENEOUS[tag]
            and wrap["rows"][tag]["surviving_block_anti_hermitian"]
            == (not CORNER_HOLLOW[tag])
            for tag in TAGS
        )
        and wrap["rank_symbolic"] == RANK_SYMBOLIC
        and wrap["rank_numeric"] == (RANK_NUMERIC,) * 3
        and homogeneity_kills == claims["homogeneity_kills"]
        and facts.exact_no_float
    )

    required = tuple(claims["required_scope_keys"])
    budget = DEEP_RUNTIME_BUDGET_SEC if facts.deep else RUNTIME_BUDGET_SEC
    gate_h = bool(
        set(facts.scope) == set(required)
        and all(facts.scope[key] for key in required)
        and len(MUTATIONS) == 15
        and len(set(MUTATIONS)) == 15
        and set(MUTATION_GATE) == set(MUTATIONS)
        and set(MUTATION_GATE.values()) == set("ABCDEFGH")
        and N5_FENCE.count("\n") + 1 <= 10
        and N5_FENCE.count("\n") + 1 >= 8
        and POOL_TWO_LEADS == 5
        and REMAINING_AXES == 2
        and elapsed_ns <= budget * 1_000_000_000
    )

    return {"A": gate_a, "B": gate_b, "C": gate_c, "D": gate_d,
            "E": gate_e, "F": gate_f, "G": gate_g, "H": gate_h}


